questions.question_text:
What are the coordinates of the point $P$ shown below?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw[->] (0,0)--(-2.9,-2.9) node[below left,font=\scriptsize]{$x$};
\draw[->] (0,0)--(6.3,0) node[right,font=\scriptsize]{$y$};
\draw[->] (0,0)--(0,4.6) node[above,font=\scriptsize]{$z$};
\node[above left,font=\scriptsize] at (0,0) {$O$};
\foreach \a in {1,2,3,4,5} { \draw (-0.5*\a-0.1,-0.5*\a+0.1)--(-0.5*\a+0.1,-0.5*\a-0.1); \node[left,font=\scriptsize] at (-0.5*\a-0.16,-0.5*\a) {$\a$}; }
\foreach \b in {1,2,3,4,5,6} { \draw (\b,-0.1)--(\b,0.1); \node[below,font=\scriptsize] at (\b,-0.12) {$\b$}; }
\foreach \c in {1,2,3,4} { \draw (-0.1,\c)--(0.1,\c); \node[left,font=\scriptsize] at (-0.12,\c) {$\c$}; }
\draw[dashed,gray] (-0.5,-0.5)--(4.5,-0.5)--(4.5,3.5);
\fill (4.5,3.5) circle (2.2pt);
\node[above right,font=\footnotesize] at (4.5,3.5) {$P$};
\end{tikzpicture}
[/tikz]
